WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, customer_id ORDER BY discount NULLS LAST, id) AS dedup_rank FROM orders) t WHERE dedup_rank = 1) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, CASE WHEN discount >= 0.37 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_tier, AVG(shipping_fee) AS avg_shipping_fee, COUNT(DISTINCT channel) AS distinct_channels, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', order_date) ORDER BY AVG(shipping_fee) DESC) AS avg_shipping_fee_dense_rank FROM latest GROUP BY DATE_TRUNC('QUARTER', order_date), CASE WHEN discount >= 0.37 THEN 'PREMIUM' ELSE 'STANDARD' END;
